'use strict';
// The settings records (templates/settings-records.json, generated by scripts/build-settings-records.js): one record for
// every setting, indicator, door and action, with its plain-words help, who may change it and where each page draws it.
// load() reads and checks the file once; a broken file throws a clear error. The records hold words only, never secrets.
const fs = require('fs');
const path = require('path');

const FILE = path.join(__dirname, '..', 'templates', 'settings-records.json');
const KINDS = ['setting', 'indicator', 'door', 'action'];
const DANGER = ['everyday', 'care', 'dangerous'];
const WHO = ['admin', 'member', 'both'];
const LEAD = ['apply', 'confirm', 'screen', 'none'];
const SURFACES = ['desktop', 'phone', 'agent-settings', 'users', 'modules', 'local-models', 'changes', 'welcome', 'simple-desktop', 'simple-phone'];
const ID_RE = /^OPT-\d{4,}$/;
const SELECTOR_RE = /^#[A-Za-z][\w:.-]*$/;
const HIDDEN = new Set(['facts', 'storedAs']);

let cache = null;   // { file, version, records, byId }

/** Checks a parsed document; throws Error('settings-records: ...') on the first problem. */
function validate(doc) {
  const bad = (msg) => { throw new Error(`settings-records: ${msg}`); };
  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) bad('the file must hold an object { version, records }');
  if (typeof doc.version !== 'string' || !doc.version) bad('missing version');
  if (!Array.isArray(doc.records)) bad('records must be a list');
  const ids = new Set();
  for (const r of doc.records) {
    if (!r || typeof r !== 'object' || Array.isArray(r)) bad('a record is not an object');
    if (typeof r.id !== 'string' || !ID_RE.test(r.id)) bad(`bad id ${JSON.stringify(r.id)}`);
    if (ids.has(r.id)) bad(`duplicate id ${r.id}`);
    ids.add(r.id);
    if (!KINDS.includes(r.kind)) bad(`${r.id}: kind ${JSON.stringify(r.kind)} is not one of ${KINDS.join(', ')}`);
    if (!DANGER.includes(r.danger)) bad(`${r.id}: danger ${JSON.stringify(r.danger)} is not one of ${DANGER.join(', ')}`);
    if (!WHO.includes(r.who)) bad(`${r.id}: who ${JSON.stringify(r.who)} is not one of ${WHO.join(', ')}`);
    if (!LEAD.includes(r.lead)) bad(`${r.id}: lead ${JSON.stringify(r.lead)} is not one of ${LEAD.join(', ')}`);
    if (typeof r.name !== 'string' || !r.name) bad(`${r.id}: missing name`);
    if (typeof r.restart !== 'boolean') bad(`${r.id}: restart must be true or false`);
    if (!Array.isArray(r.labels) || r.labels.some((x) => typeof x !== 'string')) bad(`${r.id}: labels must be a list of words`);
    if (!Array.isArray(r.words) || r.words.some((x) => typeof x !== 'string')) bad(`${r.id}: words must be a list of words`);
    if (!Array.isArray(r.anchors)) bad(`${r.id}: anchors must be a list`);
    for (const a of r.anchors) {
      // an anchor is { surface, selector } (a control's id) or { surface, label } (the row's words): exactly one of the two
      const ok = a && typeof a === 'object' && !Array.isArray(a) && SURFACES.includes(a.surface)
        && ((a.selector !== undefined) !== (a.label !== undefined))
        && (a.selector !== undefined
          ? typeof a.selector === 'string' && SELECTOR_RE.test(a.selector)
          : typeof a.label === 'string' && a.label.trim() !== '');
      if (!ok) bad(`${r.id}: malformed anchor ${JSON.stringify(a)}`);
    }
  }
  for (const r of doc.records) {
    if (r.mergedInto !== undefined && (typeof r.mergedInto !== 'string' || !ids.has(r.mergedInto) || r.mergedInto === r.id)) {
      bad(`${r.id}: mergedInto ${JSON.stringify(r.mergedInto)} does not point at another record`);
    }
  }
  return doc;
}

/** Reads and validates the records once (later calls return the same set). `file` is for tests. */
function load(file = FILE) {
  if (cache && cache.file === file) return cache;
  let doc;
  try { doc = JSON.parse(fs.readFileSync(file, 'utf8')); }
  catch (e) { throw new Error(`settings-records: cannot read ${path.basename(file)}: ${e.message}`); }
  validate(doc);
  cache = { file, version: doc.version, records: doc.records, byId: new Map(doc.records.map((r) => [r.id, r])) };
  return cache;
}

const all = () => load().records.slice();
const byId = (id) => load().byId.get(String(id)) || null;
const version = () => load().version;

/** Admins see every record; everyone else only those a member may see (who: member | both). */
function forUser(user, { isAdmin = false } = {}) {
  void user;
  return load().records.filter((r) => isAdmin || r.who === 'member' || r.who === 'both');
}

/** What a page needs: the record without its hidden facts note and storage key. */
function view(record) {
  const out = {};
  for (const k of Object.keys(record)) if (!HIDDEN.has(k)) out[k] = record[k];
  return out;
}

/** The body of GET /api/settings-records. leadTool turns true in phase 2, when the lead's settings tool exists. */
function routeBody(user, { isAdmin = false } = {}) {
  return { version: version(), leadTool: false, records: forUser(user, { isAdmin }).map(view) };
}

module.exports = { load, all, byId, version, forUser, view, routeBody, validate, KINDS, DANGER, WHO, LEAD, SURFACES, FILE };
